using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
class UpdateTests {
 static void Check(bool pass,string text){if(!pass)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 static string Fixture(string assets){return "{\"tag_name\":\"v0.6.1\",\"assets\":"+assets+"}";}
 static string Asset(string name){return "{\"name\":\""+name+"\",\"browser_download_url\":\"https://github.com/CS-Colin/MultiVPNConnect/releases/download/v0.6.1/"+name+"\"}";}
 static void Reject(string json,string text){bool failed=false;try{UpdateRelease.Parse(json);}catch{failed=true;}Check(failed,text);}
 static int Main(string[] args){try{
  string json=Fixture("["+Asset("MultiVPNConnect-Setup.exe")+","+Asset("SHA256SUMS.txt")+"]");var legacy=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);Check(legacy["assets"] is ArrayList,"Fixture reproduces the ArrayList that broke the old updater");var release=UpdateRelease.Parse(json);Check(release.Version==new Version("0.6.1")&&release.Installer.EndsWith("MultiVPNConnect-Setup.exe"),"Updater accepts the real serializer's release asset collection");Reject(Fixture("[]"),"Missing release assets produce a clear error");Reject(Fixture("null"),"Null asset lists are rejected");Reject(Fixture("["+Asset("MultiVPNConnect-Setup.exe")+","+Asset("MultiVPNConnect-Setup.exe")+","+Asset("SHA256SUMS.txt")+"]"),"Duplicate installer assets are rejected");Reject(json.Replace("https://github.com/","https://example.com/"),"Foreign download locations are rejected");string hash=new string('a',64);Check(UpdateRelease.InstallerHash(hash+"  MultiVPNConnect-Setup.exe\r\n")==hash,"Installer checksum is matched by exact filename");bool failed=false;try{UpdateRelease.InstallerHash(hash+"  NotMultiVPNConnect-Setup.exe");}catch{failed=true;}Check(failed,"Filename suffix lookalikes cannot supply a checksum");if(args.Length>0){var live=UpdateRelease.Parse(File.ReadAllText(args[0]));Check(live.Installer!=null&&live.Checksums!=null,"Published GitHub release response parses successfully");}return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
